// Seu primeiro script: o drone planta capim, espera e colhe.
plantar(Planta.CAPIM);
mover(Dir.LESTE);
plantar(Planta.CAPIM);

// O capim leva um tempo para ficar pronto.
esperar(130);

// Colhe as duas casas. Capim pronto vira feno.
colher();
mover(Dir.OESTE);
colher();

registrar("Feno no estoque:", estoque(Item.FENO));
